def top_k_san_pham(orders, k):
    doanh_thu = {}
    for o in orders:
        doanh_thu[o["sp"]] = doanh_thu.get(o["sp"], 0) + o["sl"] * o["gia"]
    xep = sorted(doanh_thu.items(), key=lambda x: (-x[1], x[0]))
    return [sp for sp, _ in xep[:k]]

def ti_le_chuyen_doi(phien):
    df = phien.assign(mua=phien["mua"].fillna(0))
    out = (df.groupby("kenh", as_index=False)
             .agg(so_phien=("mua", "size"), ti_le=("mua", "mean")))
    out["ti_le"] = out["ti_le"].round(3)
    return out.sort_values("ti_le", ascending=False).reset_index(drop=True)
